<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Assessment Report #<?=e($assessment['id'])?></title><link rel="stylesheet" href="<?=url('assets/css/app.css')?>"></head><body class="report-page"><div class="report-wrap"><div class="report-toolbar"><button class="btn primary" onclick="window.print()">Print / Save PDF</button><a class="btn ghost" href="<?=url('assessments/'.$assessment['id'])?>">Back to Assessment</a></div><header class="report-cover"><div class="eyebrow">SECURITY VENDOR ASSESSMENT</div><h1>DNET Mailing Vendor</h1><h2><?=e($assessment['vendor_name'])?></h2><p>Assessment date: <?=date('d M Y',strtotime($assessment['assessment_date']))?></p><div class="final-score"><span>Final Score</span><strong><?=number_format($score['final'],1)?>%</strong><b><?=e($rating)?></b></div></header><section class="report-section"><h2>Executive Summary</h2><div class="report-stats"><div><b><?=$score['answered']?></b><span>Answered</span></div><div><b><?=$score['counts']['Compliant']?></b><span>Compliant</span></div><div><b><?=$score['counts']['Partially Compliant']?></b><span>Partial</span></div><div><b><?=$score['counts']['Non-Compliant']?></b><span>Non-Compliant</span></div><div><b><?=$score['critical_findings']?></b><span>Critical Findings</span></div></div><table><thead><tr><th>Parameter</th><th>Weight</th><th>Score</th><th>Weighted</th></tr></thead><tbody><?php foreach($parameters as $p): $ps=$score['parameters'][$p['id']]; ?><tr><td><?=e($p['name'])?></td><td><?=$p['weight']?>%</td><td><?=number_format($ps['score'],1)?>%</td><td><?=number_format($ps['weighted'],2)?></td></tr><?php endforeach; ?></tbody></table></section><section class="report-section"><h2>Critical Findings</h2><?php if(!$findings): ?><p class="muted">Tidak ada critical finding yang tercatat.</p><?php else: ?><div class="finding-list"><?php foreach($findings as $f): ?><div class="finding"><div><span class="control-id"><?=e($f['control_code'])?></span><span class="badge critical">Critical</span><h3><?=e($f['question'])?></h3></div><p><b>Finding:</b> <?=e($f['finding'] ?: 'Belum diisi')?></p><p><b>Recommendation:</b> <?=e($f['recommendation'] ?: $f['baseline'])?></p></div><?php endforeach; ?></div><?php endif; ?></section><section class="report-section"><h2>Recommendations</h2><?php foreach($recommendations as $r): ?><div class="recommendation"><b><?=e($r['control_code'])?></b><span><?=e($r['recommendation'])?></span></div><?php endforeach; ?></section><footer>Generated by DNET Vendor Assessment · Audit trail based on questionnaire workflow.</footer></div></body></html>
